mapper.select:
SELECT
a.*,
CONCAT(
DATE_FORMAT(a.START_DATE,'%m-%d'),
'至' ,
DATE_FORMAT(a.END_DATE,'%m-%d')
) AS EFFECTIVE_DATE
FROM
`inspection`.`inspection_supplement_task` a
WHERE
1=1

    AND a.TASK_YEAR = #{params.TASK_YEAR}


    AND a.TASK_ID =#{params.TASK_ID}


    AND a.TASK_NAME LIKE '%${params.TASK_NAME}%'


    AND a.TASK_TYPE = #{params.TASK_TYPE}


    LIMIT ${params.page},${params.rows}

SELECT
COUNT(0)
FROM
`inspection`.`inspection_supplement_task` a
WHERE
1=1

    AND a.TASK_YEAR = #{params.TASK_YEAR}


    AND a.TASK_ID =#{params.TASK_ID}


    AND a.TASK_NAME LIKE '%${params.TASK_NAME}%'


    AND a.TASK_TYPE = #{params.TASK_TYPE}
